function groupTasks(tasks) {
  const groups = new Map();

  for (const task of tasks) {
    const status = task.done ? "finished" : "open";
    const list = groups.get(status) ?? [];
    list.push(task.title);
    groups.set(status, list);
  }

  return Object.fromEntries(groups);
}

function buildSearchIndex(documents) {
  const index = Object.create(null);

  for (const document of documents) {
    const words = document.title.toLowerCase().split(/\s+/);
    for (const word of new Set(words)) {
      (index[word] ??= []).push(document.id);
    }
  }

  return index;
}

async function runQueue(jobs, limit) {
  if (limit < 1) throw new RangeError("Choose a positive limit");

  const results = [];
  let next = 0;

  async function worker() {
    while (next < jobs.length) {
      const index = next++;
      results[index] = await jobs[index]();
    }
  }

  const workers = Array.from(
    { length: Math.min(limit, jobs.length) },
    () => worker()
  );
  await Promise.all(workers);
  return results;
}

from collections import defaultdict
from decimal import Decimal


def totals_by_day(expenses):
    totals = defaultdict(Decimal)

    for expense in expenses:
        day = expense["date"]
        amount = Decimal(expense["amount"])
        totals[day] += amount

    return dict(sorted(totals.items()))

def lower_bound(values, target):
    left = 0
    right = len(values)

    while left < right:
        middle = (left + right) // 2
        if values[middle] < target:
            left = middle + 1
        else:
            right = middle

    return left


def contains(values, target):
    index = lower_bound(values, target)
    return index < len(values) and values[index] == target

from collections import deque


def shortest_distance(graph, start, end):
    queue = deque([(start, 0)])
    seen = {start}

    while queue:
        vertex, distance = queue.popleft()
        if vertex == end:
            return distance

        for neighbor in graph.get(vertex, ()):
            if neighbor not in seen:
                seen.add(neighbor)
                queue.append((neighbor, distance + 1))

    return None

#include <vector>

std::vector<int> mergeSorted(const std::vector<int>& left,
                             const std::vector<int>& right) {
    std::vector<int> result;
    auto first = left.begin();
    auto second = right.begin();

    while (first != left.end() && second != right.end()) {
        if (*first <= *second) {
            result.push_back(*first++);
        } else {
            result.push_back(*second++);
        }
    }

    result.insert(result.end(), first, left.end());
    result.insert(result.end(), second, right.end());
    return result;
}

#include <stack>
#include <string>

bool isBalanced(const std::string& text) {
    std::stack<char> expected;

    for (char ch : text) {
        if (ch == '(') {
            expected.push(')');
        } else if (ch == '[') {
            expected.push(']');
        } else if (ch == ')' || ch == ']') {
            if (expected.empty() || expected.top() != ch) {
                return false;
            }
            expected.pop();
        }
    }

    return expected.empty();
}

#include <cstddef>
#include <unordered_map>
#include <vector>

std::vector<int> countDistinct(const std::vector<int>& values,
                              std::size_t width) {
    if (width == 0 || width > values.size()) return {};

    std::unordered_map<int, int> counts;
    std::vector<int> result;

    for (std::size_t i = 0; i < values.size(); ++i) {
        ++counts[values[i]];
        if (i >= width && --counts[values[i - width]] == 0) {
            counts.erase(values[i - width]);
        }
        if (i + 1 >= width) {
            result.push_back(static_cast<int>(counts.size()));
        }
    }

    return result;
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Enrollments {
    record Student(String name, String course) {}

    static Map<String, List<String>> byCourse(List<Student> students) {
        Map<String, List<String>> courses = new HashMap<>();
        for (Student student : students) {
            courses.computeIfAbsent(student.course(), key -> new ArrayList<>())
                   .add(student.name());
        }
        return courses;
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.PriorityQueue;

class Rankings {
    static List<Integer> topThree(int[] scores) {
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        for (int score : scores) {
            heap.add(score);
            if (heap.size() > 3) {
                heap.poll();
            }
        }

        List<Integer> result = new ArrayList<>();
        while (!heap.isEmpty()) {
            result.add(heap.remove());
        }
        Collections.reverse(result);
        return result;
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;

class LookupCache<T> {
    private final Map<String, T> values = new HashMap<>();
    private final Function<String, T> loader;

    LookupCache(Function<String, T> loader) {
        this.loader = loader;
    }

    T get(String key) {
        return values.computeIfAbsent(key, loader);
    }

    void invalidate(String key) {
        values.remove(key);
    }
}

